import re

def strip_markdown_links(text):
    """
    Replaces Markdown inline links like [label](url) with just label.
    """
    # Regex to find patterns like [label](url)
    # \[([^\]]+)\] matches the label inside square brackets
    # \(([^)]+)\) matches the URL inside parentheses
    pattern = r"\[([^\]]+)\]\(([^)]+)\)"

    # Replacement function: only keep the first captured group (the label)
    def replacer(match):
        return match.group(1)

    return re.sub(pattern, replacer, text)

