import urllib.parse

def parse_query_string(query):
    """
    Parses a URL query string into a dict mapping each key to a list of decoded values.
    Ignores a leading ?. Uses urllib.parse semantics for percent decoding and blank values.
    """
    if query.startswith('?'):
        query = query[1:]

    if not query:
        return {}

    parsed_query = urllib.parse.parse_qs(query)
    result = {}

    for key, values in parsed_query.items():
        # parse_qs returns values as lists of strings.
        # We need to handle potential blank values if they exist in the input,
        # although parse_qs usually handles empty values by not including them
        # or returning an empty list depending on the input format.
        # The requirement is to map key to a list of decoded values.
        result[key] = values

    return result

