def parse_size_bytes(value):
    if not isinstance(value, str):
        raise ValueError("Input must be a string")

    value = value.strip()
    if not value:
        raise ValueError("Input string cannot be empty")

    # Check for negative numbers (though int conversion handles this, explicit check is good)
    if value.startswith('-'):
        raise ValueError("Negative numbers are not allowed")

    # Determine the numeric part and the unit part
    unit = ""
    numeric_str = value

    # Check for units (case-insensitive)
    if value.upper().endswith('B'):
        unit = 'B'
        numeric_str = value[:-1]
    elif value.upper().endswith('KB'):
        unit = 'KB'
        numeric_str = value[:-2]
    elif value.upper().endswith('MB'):
        unit = 'MB'
        numeric_str = value[:-2]
    elif value.upper().endswith('GB'):
        unit = 'GB'
        numeric_str = value[:-2]
    else:
        # If no recognized unit suffix, assume it's just a number (no unit)
        unit = ''
        numeric_str = value

    try:
        # Reject decimals: check if the numeric string contains a decimal point
        if '.' in numeric_str:
            raise ValueError("Decimals are not allowed")

        # Parse the integer
        size = int(numeric_str)

        # Reject negative numbers (already partially checked, but ensures final result is positive)
        if size < 0:
            raise ValueError("Negative numbers are not allowed")

        # Calculate the final size based on the unit
        if unit == 'B':
            return size
        elif unit == 'KB':
            return size * 1024
        elif unit == 'MB':
            return size * 1024**2
        elif unit == 'GB':
            return size * 1024**3
        else:
            # If unit is empty, it's just the integer value (no unit suffix found)
            return size

    except ValueError as e:
        # Re-raise with a more specific message if it's a parsing error we control
        if "Decimals are not allowed" in str(e) or "Negative numbers are not allowed" in str(e):
            raise ValueError(f"Invalid format or value: {value}") from e
        # If it's a general int conversion error (e.g., non-numeric characters remaining)
        raise ValueError(f"Invalid size format or unknown unit: {value}") from e
    except Exception as e:
        # Catch any other unexpected errors
        raise ValueError(f"An unexpected error occurred while parsing {value}: {e}")

