def parse_semver(value):
    """
    Parses a semantic version string MAJOR.MINOR.PATCH with an optional leading v.
    Returns a tuple of three integers (MAJOR, MINOR, PATCH).
    Raises ValueError if the format is incorrect (missing parts, non-integers, or negative numbers).
    """
    if value.startswith('v'):
        value = value[1:]

    parts = value.split('.')

    if len(parts) != 3:
        raise ValueError("Semantic version string must have exactly three parts (MAJOR.MINOR.PATCH).")

    major_str, minor_str, patch_str = parts[0], parts[1], parts[2]

    try:
        major = int(major_str)
        minor = int(minor_str)
        patch = int(patch_str)
    except ValueError:
        raise ValueError("All version components must be integers.")

    if major < 0 or minor < 0 or patch < 0:
        raise ValueError("Version components cannot be negative.")

    return (major, minor, patch)

