def group_sum(rows, key, value_key):
    result = {}
    for row in rows:
        # Determine the grouping key. If key is None, use None.
        group_key = row.get(key)
        if group_key is None:
            group_key = None

        # Determine the value to sum. If value_key is missing, it's 0.
        value = row.get(value_key, 0)

        # Update the result dictionary
        if group_key not in result:
            result[group_key] = 0

        result[group_key] += value

    return result

