def project_fields(rows, fields):
    """
    Returns new dictionaries containing only the requested fields that exist in each input row.
    Preserves row order and field order.
    """
    result = []
    for row in rows:
        new_row = {}
        for field in fields:
            if field in row:
                new_row[field] = row[field]
        result.append(new_row)
    return result

