def reachable_nodes(graph, start):
    if start not in graph:
        # If the start node is not in the graph keys, it has no outgoing neighbors,
        # but it is still reachable (itself).
        return [start]

    visited = set()
    stack = [start]
    reachable = set()

    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            reachable.add(node)

            # Get neighbors, default to an empty list if the node is not in graph
            neighbors = graph.get(node, [])
            for neighbor in neighbors:
                if neighbor not in visited:
                    stack.append(neighbor)

    # Return a sorted list of all reachable nodes
    return sorted(list(reachable))

