from collections import deque

def shortest_path_unweighted(graph, start, goal):
    if start == goal:
        return [start]

    # Queue for BFS: stores paths, not just nodes, to reconstruct the path easily.
    # Each element in the queue will be a list representing the path from start to the current node.
    queue = deque([[start]])
    visited = {start}

    while queue:
        path = queue.popleft()
        current_node = path[-1]

        # Check neighbors in the order they appear in the graph's adjacency list
        if current_node in graph:
            neighbors = graph[current_node]
            for neighbor in neighbors:
                if neighbor == goal:
                    return path + [neighbor]

                if neighbor not in visited:
                    visited.add(neighbor)
                    new_path = path + [neighbor]
                    queue.append(new_path)

    return None

