    # 0: unvisited (white)
    # 1: visiting (gray - currently in the recursion stack)
    # 2: visited (black - finished processing)
    state = {}

    # Initialize all nodes to unvisited
    all_nodes = set(graph.keys())
    for neighbors in graph.values():
        for neighbor in neighbors:
            all_nodes.add(neighbor)

    for node in all_nodes:
        state[node] = 0

    def dfs(node):
        """
        Recursive helper function for DFS. Returns True if a cycle is found starting from this path.
        """
        state[node] = 1  # Mark as visiting (gray)

        # Get neighbors, handling cases where a node might be a neighbor but not a key in the graph dict
        neighbors = graph.get(node, [])

        for neighbor in neighbors:
            if state.get(neighbor, 0) == 1:
                # Found a back edge to a node currently in the recursion stack (gray) -> Cycle detected
                return True

            if state.get(neighbor, 0) == 0:
                # Unvisited neighbor
                if dfs(neighbor):
                    return True

        state[node] = 2  # Mark as visited (black)
        return False

    # Iterate through all nodes to ensure disconnected components are checked
    for node in all_nodes:
        if state[node] == 0:
            if dfs(node):
                return True

    return False

