def dependency_order(dependencies):
    """
    Calculates a topological sort of the dependencies.

    :param dependencies: A dictionary where keys are items and values are lists of items they depend on.
    :return: A deterministic list where dependencies appear before dependents, or raises ValueError on cycles.
    """
    # 1. Build the graph structure and identify all nodes
    all_items = set(dependencies.keys())
    for prereqs in dependencies.values():
        all_items.update(prereqs)

    # Initialize in-degree for all nodes
    in_degree = {item: 0 for item in all_items}

    # Calculate in-degrees: item depends on prereqs, so prereq -> item
    for item, prereqs in dependencies.items():
        for prereq in prereqs:
            if prereq in in_degree:
                in_degree[item] += 1
            else:
                # This case should ideally not happen if all_items is calculated correctly,
                # but handles cases where a prereq is mentioned but not in the initial set of keys.
                in_degree[prereq] = 0

    # 2. Initialize the priority queue (min-heap) with nodes having an in-degree of 0
    import heapq

    ready_heap = []
    for item in sorted(list(all_items)):
        if in_degree[item] == 0:
            heapq.heappush(ready_heap, item)

    result = []

    # 3. Process the heap
    while ready_heap:
        # Choose the lexicographically smallest item first
        current_item = heapq.heappop(ready_heap)
        result.append(current_item)

        # Find items that depend on current_item (successors)
        # We need to iterate through the original dependencies to find dependents.
        for item, prereqs in dependencies.items():
            if current_item in prereqs:
                # current_item is a prerequisite for 'item'
                if item in in_degree:
                    in_degree[item] -= 1
                    if in_degree[item] == 0:
                        heapq.heappush(ready_heap, item)

    # 4. Cycle detection
    if len(result) != len(all_items):
        raise ValueError("Cycle detected in dependencies")

    return result

