def reverse_adjacency(graph):
    """
    Computes the reverse adjacency list of a graph represented by an adjacency mapping.

    Args:
        graph (dict): An adjacency mapping where keys are nodes and values are lists
                      of their outgoing neighbors.

    Returns:
        dict: A dictionary where keys are nodes and values are sorted lists of
              incoming neighbors. Includes nodes that only appear as neighbors.
    """
    reverse_graph = {}

    # Initialize all nodes present in the graph (as keys)
    for node in graph:
        if node not in reverse_graph:
            reverse_graph[node] = []

    # Initialize nodes that only appear as neighbors
    all_nodes = set(graph.keys())
    for neighbors in graph.values():
        for neighbor in neighbors:
            if neighbor not in reverse_graph:
                reverse_graph[neighbor] = []
                all_nodes.add(neighbor)

    # Populate the reverse adjacency list
    for node, neighbors in graph.items():
        for neighbor in neighbors:
            if neighbor in reverse_graph:
                reverse_graph[neighbor].append(node)

    # Sort the incoming neighbors for each node
    for node in reverse_graph:
        reverse_graph[node].sort()

    return reverse_graph

