def json_get_path(data, path, default=None):
    if not path:
        return data

    current_data = data
    path_parts = path.split('.')

    for part in path_parts:
        if isinstance(current_data, dict):
            if part in current_data:
                current_data = current_data[part]
            else:
                return default
        elif isinstance(current_data, list):
            try:
                index = int(part)
                if 0 <= index < len(current_data):
                    current_data = current_data[index]
                else:
                    return default
            except ValueError:
                # If the part is not an integer for a list access, it's invalid
                return default
        else:
            # If we are trying to access a key/index on a non-container type
            return default

    return current_data

