def flatten_dict(data, sep='.'):
    """
    Flattens nested dictionaries into a single dictionary with joined keys.
    Non-dict values are leaves. Preserves insertion traversal order.
    """
    result = {}

    def _flatten(d, parent_key=''):
        if isinstance(d, dict):
            for k, v in d.items():
                new_key = parent_key + sep + k if parent_key else k
                if isinstance(v, dict):
                    _flatten(v, new_key)
                else:
                    result[new_key] = v
        else:
            # This case should ideally not be hit if the initial call is on a dict,
            # but handles cases where a non-dict is passed directly.
            # For the top level, we assume 'data' is a dict.
            pass

    _flatten(data)
    return result

