def expand_ranges(ranges):
    expanded_list = []
    for start, end in ranges:
        if start > end:
            raise ValueError("Start of range cannot be greater than end of range.")

        current = start
        while current <= end:
            expanded_list.append(current)
            current += 1

    return expanded_list

